export const statuses=['Not recorded','Awaiting permission','Details recorded by creator','Not applicable — creator selected','Do not use'];
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function targets(p){return [{type:'project',id:p.id,label:p.title},...['characters','locations','assets'].flatMap(k=>p[k].map(x=>({type:{characters:'character',locations:'location',assets:'asset'}[k],id:x.id,label:x.name}))),...p.scenes.flatMap(s=>[{type:'scene',id:s.id,label:s.title},...s.panels.map((x,i)=>({type:'panel',id:x.id,label:s.title+' · Panel '+(i+1)}))])];}
export function review(p){return (p.materials||[]).flatMap(m=>{const messages=[];if(['Not recorded','Awaiting permission'].includes(m.status))messages.push('Review permission/use status.');if(m.status==='Do not use'&&m.links.length)messages.push('Marked do not use, with production links.');if(m.includeCredit&&!m.credit.trim())messages.push('Selected public credit has no text.');if(!m.links.length)messages.push('No production uses linked yet.');if(m.links.some(l=>!targets(p).some(t=>t.type===l.type&&t.id===l.id)))messages.push('A linked production item is missing.');return messages.map(message=>({id:m.id,message}));});}
export function creditsHtml(p){return '<!doctype html><html lang="en"><meta charset="utf-8"><title>Creator-selected credits</title><style>body{font:18px Georgia;max-width:700px;margin:50px auto;padding:20px}li{white-space:pre-wrap;margin:20px 0}</style><h1>Creator-selected credits</h1><p>Prepared for creator review. This sheet does not publish the project.</p><ul>'+(p.materials||[]).filter(m=>m.includeCredit&&m.credit.trim()).map(m=>'<li>'+esc(m.credit)+'</li>').join('')+'</ul></html>';}
export function validateMaterials(p){if(p.materials===undefined)return;if(!Array.isArray(p.materials))throw Error('Invalid materials.');const ids=new Set();for(const m of p.materials){if(!m||typeof m.id!=='string'||!m.id||ids.has(m.id))throw Error('Invalid or duplicate material id.');ids.add(m.id);for(const key of ['title','kind','reference','language','notes','credit','variantOf'])if(typeof m[key]!=='string')throw Error('Invalid material '+key);if(!m.title.trim()||!m.kind.trim()||!statuses.includes(m.status)||typeof m.includeCredit!=='boolean'||!Array.isArray(m.links))throw Error('A title, creator-described kind and valid status are required.');for(const l of m.links)if(!l||!['project','character','location','asset','scene','panel'].includes(l.type)||typeof l.id!=='string'||!l.id||!['informs','adapted into','visual reference for'].includes(l.relationship))throw Error('Invalid material link.');}for(const m of p.materials){let id=m.variantOf,seen=new Set([m.id]);while(id){if(seen.has(id)||!ids.has(id))throw Error('Variant links must reference another material without a cycle.');seen.add(id);id=p.materials.find(x=>x.id===id).variantOf;}}}
export function createStewardship({project,save,refresh,navigate}){
 let selected='',tab='materials',draft=null,context=null;
 const records=()=>project().materials||[];
 const button=(action,label,attrs='')=>'<button type="button" class="btn small" data-st="'+action+'" '+attrs+'>'+label+'</button>';
 const field=(key,label,value,area=false)=>'<label class="field">'+label+(area?'<textarea name="'+key+'">'+esc(value)+'</textarea>':'<input name="'+key+'" value="'+esc(value)+'">')+'</label>';
 function editor(m){return '<form id="st-editor" class="panel form-grid">'+field('title','Material title',m.title)+field('kind','Kind — described by you',m.kind)+field('reference','Reference',m.reference)+field('language','Language label',m.language)+'<label class="field">Variant of<select name="variantOf"><option value="">None</option>'+records().filter(x=>x.id!==m.id).map(x=>'<option value="'+esc(x.id)+'" '+(m.variantOf===x.id?'selected':'')+'>'+esc(x.title)+'</option>').join('')+'</select></label><label class="field">Creator-recorded use status<select name="status">'+statuses.map(s=>'<option '+(m.status===s?'selected':'')+'>'+esc(s)+'</option>').join('')+'</select></label>'+field('notes','Internal notes — non-sensitive only',m.notes,true)+field('credit','Public credit line',m.credit,true)+'<label><input name="includeCredit" type="checkbox" '+(m.includeCredit?'checked':'')+'> Include this credit line on the optional public sheet</label><div class="actions">'+button('save','Save material')+button('cancel','Cancel')+'</div><p id="st-error" role="alert"></p></form>';}
 function uses(m){return m.links.map((l,i)=>'<p>'+button('visit',esc(targets(project()).find(t=>t.type===l.type&&t.id===l.id)?.label||'Missing item'),'data-type="'+esc(l.type)+'" data-id="'+esc(l.id)+'"')+' '+esc(l.relationship)+' '+button('unlink','Remove link','data-index="'+i+'"')+'</p>').join('');}
 function detail(m){return '<h2>'+esc(m.title)+'</h2><p>'+esc(m.kind)+' · '+esc(m.language)+'</p><p>'+esc(m.status)+'</p><p>Variant of: '+esc(records().find(x=>x.id===m.variantOf)?.title||'None selected')+'</p><p>'+esc(m.reference)+'</p><p style="white-space:pre-wrap">'+esc(m.notes)+'</p>'+button('edit','Edit record')+'<h3>Linked production uses</h3>'+uses(m)+'<form id="st-link"><label>Production item<select name="target">'+targets(project()).map(t=>'<option value="'+esc(JSON.stringify([t.type,t.id]))+'" '+(context?.id===t.id&&context?.type===t.type?'selected':'')+'>'+esc(t.type+' · '+t.label)+'</option>').join('')+'</select></label><label>Relationship<select name="relationship">'+['informs','adapted into','visual reference for'].map(r=>'<option>'+r+'</option>').join('')+'</select></label>'+button('link','Link to production')+'</form>';}
 function render(){const p=project(),m=records().find(x=>x.id===selected)||records()[0];if(m)selected=m.id;return '<div class="view-head"><div><div class="eyebrow">Creator records</div><h1>Story stewardship</h1><p>Trace materials and variants through your production.</p></div>'+button('new','Add material')+'</div><div class="tabs">'+['materials','review','credits'].map(t=>button('tab',t,'data-value="'+t+'"')).join('')+button('copy','Copy existing story notes')+'</div><p class="hint">Based on creator-entered records; not independently verified. Record only non-sensitive material appropriate to keep in this browser.</p>'+(draft?editor(draft):tab==='review'?'<section class="panel"><h2>Private Stewardship Review</h2><p>'+records().length+' materials · '+records().reduce((n,x)=>n+x.links.length,0)+' production links</p>'+review(p).map(f=>'<p>'+button('select',esc(records().find(x=>x.id===f.id).title),'data-id="'+esc(f.id)+'"')+' '+esc(f.message)+'</p>').join('')+(review(p).length?'':'<p>No attention items found from the recorded fields.</p>')+'</section>':tab==='credits'?'<section class="panel"><h2>Optional public credit sheet</h2><p>Only explicitly selected credit lines are included. Review the sheet, then use your browser’s Print / Save as PDF command.</p>'+button('credits','Open printable sheet')+button('download','Download HTML')+'</section>':'<div class="st-layout"><section>'+records().map(x=>button('select','<strong>'+esc(x.title)+'</strong><br>'+esc(x.kind)+' · '+x.links.length+' uses<br>'+esc(x.status),'data-id="'+esc(x.id)+'" style="display:block;width:100%;text-align:left;margin-bottom:8px"')).join('')+'</section><section class="panel">'+(m?detail(m):'<h2>No materials recorded yet</h2><p>Add your original work or a reference. You choose its kind and production uses.</p>')+'</section></div>');}
 function action(b){const a=b.dataset.st,p=project(),m=records().find(x=>x.id===selected);if(a==='tab'){tab=b.dataset.value;draft=null;}if(a==='select'){selected=b.dataset.id;tab='materials';draft=null;}if(a==='new'||a==='copy')draft={id:crypto.randomUUID(),title:'',kind:'',reference:'',language:'',notes:a==='copy'?Object.entries(p.story).map(([k,v])=>k+': '+v).join('\n'):'',credit:'',variantOf:'',status:'Not recorded',includeCredit:false,links:[]};if(a==='edit')draft=structuredClone(m);if(a==='cancel')draft=null;if(a==='save'){const data=Object.fromEntries(new FormData(document.getElementById('st-editor'))),next={...draft,...data,includeCredit:data.includeCredit==='on'},all=records().filter(x=>x.id!==next.id).concat(next);try{validateMaterials({...p,materials:all});p.materials=all;selected=next.id;save();draft=null;}catch(err){document.getElementById('st-error').textContent=err.message;return;}}if(a==='link'){const f=new FormData(document.getElementById('st-link')),[type,id]=JSON.parse(f.get('target')),relationship=f.get('relationship');if(!m.links.some(l=>l.type===type&&l.id===id&&l.relationship===relationship))m.links.push({type,id,relationship});save();}if(a==='unlink'){m.links.splice(Number(b.dataset.index),1);save();}if(a==='visit'){navigate(b.dataset.type,b.dataset.id);return;}if(a==='credits'||a==='download'){const url=URL.createObjectURL(new Blob([creditsHtml(p)],{type:'text/html'}));if(a==='credits')window.open(url,'_blank','noopener');else{const link=document.createElement('a');link.href=url;link.download='creator-selected-credits.html';link.click();}setTimeout(()=>URL.revokeObjectURL(url),60000);return;}refresh();}
 return {render,action,setContext:(type,id)=>{context={type,id};tab='materials';draft=null;selected=records().find(m=>m.links.some(l=>l.type===type&&l.id===id))?.id||'';}};
}
